SELECT 'clock' AS _set,UTC_TIMESTAMP(3) AS database_now;
SELECT 'summary' AS _set,s.*,se.yeast_profile_id,yp.name AS yeast_name,se.is_demo,se.pitched_at AS original_pitched_at,(SELECT t.revision_no FROM v_current_session_timing t WHERE t.session_id=s.session_id AND t.timing_field='pitched_at' LIMIT 1) AS pitch_timing_revision_no,(SELECT t.source FROM v_current_session_timing t WHERE t.session_id=s.session_id AND t.timing_field='pitched_at' LIMIT 1) AS pitch_timing_source,IF((SELECT t.revision_no FROM v_current_session_timing t WHERE t.session_id=s.session_id AND t.timing_field='pitched_at' LIMIT 1)>1,s.pitched_at,NULL) AS manual_pitched_at,ft.expected_attenuation_min_percent,ft.expected_attenuation_max_percent,ft.expected_fg_min,ft.expected_fg_max,CONCAT(REPLACE(REPLACE(FORMAT(ft.expected_fg_min,3),',',''),'.',','),'–',REPLACE(REPLACE(FORMAT(ft.expected_fg_max,3),',',''),'.',',')) AS expected_fg_display,std.expected_fg_min AS frozen_expected_fg_min,std.expected_fg_max AS frozen_expected_fg_max,sts.template_version_id,tv.name AS template_name,tv.version_label,(SELECT COUNT(*) FROM v_active_technical_issues) AS active_issue_count,UTC_TIMESTAMP(3) AS database_now FROM v_active_session_summary s JOIN sessions se ON se.session_id=s.session_id LEFT JOIN yeast_profiles yp ON yp.yeast_profile_id=se.yeast_profile_id LEFT JOIN v_current_fermentation_target ft ON ft.session_id=s.session_id LEFT JOIN session_template_defaults std ON std.session_id=s.session_id LEFT JOIN session_template_snapshots sts ON sts.session_id=s.session_id LEFT JOIN template_versions tv ON tv.version_id=sts.template_version_id LIMIT 1;
SELECT 'series' AS _set,m.bucket_at AS at,m.sg_value AS sg,REPLACE(REPLACE(FORMAT(m.sg_value,4),',',''),'.',',') AS sg_display,m.sg_min,m.sg_max,m.temperature_min_c,m.temperature_mean_c AS temperature_c,m.temperature_max_c,m.pressure_min_bar,m.pressure_mean_bar AS pressure_bar,m.pressure_max_bar,m.sample_count,m.segment_id,m.source_kind,m.source_display,m.interval_seconds,
(SELECT te.target_value FROM process_visits pv JOIN v_current_process_visit_revision pr ON pr.visit_id=pv.visit_id JOIN session_process_targets t ON t.session_id=pv.session_id AND t.process_id=pv.process_id JOIN session_process_target_exact te ON te.session_id=t.session_id AND te.process_id=t.process_id AND te.target_id=t.target_id WHERE pv.session_id=m.session_id AND t.metric_id='beer_temperature_c' AND pr.started_at<=m.bucket_at AND (pr.ended_at IS NULL OR pr.ended_at>=m.bucket_at) ORDER BY pr.started_at,pv.visit_id LIMIT 1) AS temperature_plan_c,
(SELECT te.target_value FROM process_visits pv JOIN v_current_process_visit_revision pr ON pr.visit_id=pv.visit_id JOIN session_process_targets t ON t.session_id=pv.session_id AND t.process_id=pv.process_id JOIN session_process_target_exact te ON te.session_id=t.session_id AND te.process_id=t.process_id AND te.target_id=t.target_id WHERE pv.session_id=m.session_id AND t.metric_id='pressure_bar' AND pr.started_at<=m.bucket_at AND (pr.ended_at IS NULL OR pr.ended_at>=m.bucket_at) ORDER BY pr.started_at,pv.visit_id LIMIT 1) AS pressure_plan_bar FROM v_session_display_measurement_series m JOIN v_active_session a ON a.session_id=m.session_id JOIN v_session_graph_time_axis axis ON axis.session_id=m.session_id WHERE m.bucket_at BETWEEN axis.x_axis_started_at AND axis.x_axis_ended_at ORDER BY m.bucket_at;
SELECT 'overview_axes' AS _set,a.* FROM v_graph_definitions a JOIN v_active_session s ON s.session_id=a.session_id WHERE a.show_in_overview=1 AND a.render_scope='dashboard' ORDER BY a.sort_order;
SELECT 'measurement_history' AS _set,r.observation_id,r.observation_revision_id,r.revision_no,r.status,r.recorded_at,r.measurement_method_id AS measurement_method,r.measured_sg,r.sample_temperature_c,r.calibration_temperature_c,r.corrected_sg,r.manual_temperature_c,r.pressure_bar,r.cooler_setpoint_c,r.cooler_calibration_offset_c,r.airlock_activity,r.acetaldehyde_level,r.diacetyl_level,r.wort_like_level,r.sulfur_so2_level,r.sulfur_h2s_level,r.clarity_level,r.settling_yeast_level,r.settling_minutes,r.user_conclusion,r.note,(SELECT r0.recorded_at FROM observation_round_revisions r0 WHERE r0.observation_id=r.observation_id ORDER BY r0.revision_no ASC LIMIT 1) AS original_recorded_at,IF(r.revision_no>1,r.recorded_at,NULL) AS manual_recorded_at FROM v_current_observation_revision r JOIN v_active_session a ON a.session_id=r.session_id ORDER BY r.recorded_at;
SELECT 'notes' AS _set,n.note_id,n.noted_at,n.note_text,n.operation_id FROM session_notes n JOIN v_active_session a ON a.session_id=n.session_id ORDER BY n.noted_at;
SELECT 'observations' AS _set,r.recorded_at,r.corrected_sg,r.measured_sg,r.manual_temperature_c,r.pressure_bar,r.cooler_setpoint_c,r.airlock_activity,r.acetaldehyde_level,r.diacetyl_level,r.wort_like_level,r.sulfur_so2_level,r.sulfur_h2s_level,r.clarity_level,r.settling_yeast_level,r.settling_minutes,r.user_conclusion,r.note FROM v_current_observation_revision r JOIN v_active_session a ON a.session_id=r.session_id WHERE r.status='active' ORDER BY r.recorded_at;
SELECT 'process' AS _set,pv.visit_id,pv.process_id,ps.process_order,ps.name,ps.anchor_type,ps.anchor_biological_phase_id,ps.anchor_offset_hours,pvr.visit_revision_id,pvr.revision_no,pvr.started_at,pvr.ended_at,pvr.timing_source,pvr.revision_reason,pvr.duration_display,pvr.duration_seconds,pvr.started_display,pvr.ended_display,(SELECT r0.started_at FROM process_visit_revisions r0 WHERE r0.visit_id=pv.visit_id ORDER BY r0.revision_no ASC LIMIT 1) AS original_started_at,IF(pvr.revision_no>1,pvr.started_at,NULL) AS manual_started_at,(SELECT e.target_value FROM session_process_targets t JOIN session_process_target_exact e ON e.session_id=t.session_id AND e.process_id=t.process_id AND e.target_id=t.target_id WHERE t.session_id=pv.session_id AND t.process_id=pv.process_id AND t.metric_id='beer_temperature_c' LIMIT 1) AS target_temperature_c,(SELECT e.target_value FROM session_process_targets t JOIN session_process_target_exact e ON e.session_id=t.session_id AND e.process_id=t.process_id AND e.target_id=t.target_id WHERE t.session_id=pv.session_id AND t.process_id=pv.process_id AND t.metric_id='pressure_bar' LIMIT 1) AS target_pressure_bar FROM process_visits pv JOIN v_process_visit_timing pvr ON pvr.visit_id=pv.visit_id JOIN session_process_steps ps ON ps.session_id=pv.session_id AND ps.process_id=pv.process_id JOIN v_active_session a ON a.session_id=pv.session_id ORDER BY pvr.started_at;
SELECT 'biology' AS _set,bv.visit_id,bv.phase_id,bp.phase_order,bp.name,bp.description,bvr.visit_revision_id,bvr.revision_no,bvr.started_at,bvr.ended_at,bvr.timing_source,bvr.confidence,bvr.revision_reason,bvr.duration_display,bvr.duration_seconds,bvr.started_display,bvr.ended_display,(SELECT r0.started_at FROM biological_visit_revisions r0 WHERE r0.visit_id=bv.visit_id ORDER BY r0.revision_no ASC LIMIT 1) AS original_started_at,IF(bvr.revision_no>1,bvr.started_at,NULL) AS manual_started_at FROM biological_visits bv JOIN v_biological_visit_timing bvr ON bvr.visit_id=bv.visit_id JOIN session_biological_phases bp ON bp.session_id=bv.session_id AND bp.phase_id=bv.phase_id JOIN v_active_session a ON a.session_id=bv.session_id ORDER BY bvr.started_at;
SELECT 'bio_phases' AS _set,bp.phase_id,bp.phase_order,bp.name,bp.description FROM session_biological_phases bp JOIN v_active_session a ON a.session_id=bp.session_id ORDER BY bp.phase_order;
SELECT 'bio_criteria' AS _set,c.phase_id,p.phase_order,p.name AS phase_name,c.criterion_id,c.criterion_order,c.enabled,c.metric_id,c.model_id,c.role_id,c.label,c.exception_allowed FROM session_biological_criteria c JOIN session_biological_phases p ON p.session_id=c.session_id AND p.phase_id=c.phase_id JOIN v_active_session a ON a.session_id=c.session_id WHERE c.enabled=1 ORDER BY p.phase_order,c.criterion_order;
SELECT 'bio_params' AS _set,v.phase_id,v.criterion_id,v.model_id,v.parameter_id,v.data_type,v.real_value,v.integer_value,v.boolean_value,v.text_value FROM session_biological_criterion_parameter_values v JOIN v_active_session a ON a.session_id=v.session_id ORDER BY v.phase_id,v.criterion_id,v.parameter_id;

SELECT 'bio_correctable' AS _set,c.phase_id,c.criterion_id,c.model_id,c.parameter_id FROM session_biological_correctable_parameters c JOIN v_active_session a ON a.session_id=c.session_id ORDER BY c.phase_id,c.criterion_id,c.parameter_id;
SELECT 'bio_revisions' AS _set,r.owner_id AS phase_id,r.criterion_id,r.model_id,r.criterion_revision_id,r.revision_no,r.action,r.note,r.operation_id,r.created_at,r.evaluation_id,r.review_state,r.review_message FROM v_criterion_correction_receipts r JOIN v_active_session a ON a.session_id=r.session_id WHERE r.scope='biological' ORDER BY r.owner_id,r.criterion_id;
SELECT 'bio_revision_params' AS _set,r.phase_id,r.criterion_id,r.criterion_revision_id,p.model_id,p.parameter_id,p.data_type,p.real_value,p.integer_value,p.boolean_value,p.text_value,p.is_unset FROM v_current_biological_criterion_revision r JOIN session_biological_criterion_revision_parameter_values p ON p.criterion_revision_id=r.criterion_revision_id JOIN v_active_session a ON a.session_id=r.session_id ORDER BY r.phase_id,r.criterion_id,p.parameter_id;

SELECT 'measurement_feedback' AS _set,e.event_id,e.occurred_at,e.code,e.message,e.correlation_id FROM technical_events e JOIN v_active_session a ON a.session_id=e.session_id WHERE e.code IN ('MEASUREMENT_SAVED','MEASUREMENT_REJECTED','MEASUREMENT_SAVE_FAILED') ORDER BY e.occurred_at DESC,e.created_at DESC LIMIT 1;
SELECT 'bio_evals' AS _set,'transition' AS evidence_kind,t.transition_id,t.evaluation_id,t.current_phase_id,t.candidate_phase_id,t.active_visit_id,t.evaluated_at,t.outcome,t.confidence,t.data_quality,t.summary,t.candidate_phase_order,t.candidate_phase_name FROM v_biological_transition_evidence t JOIN v_active_session a ON a.session_id=t.session_id
UNION ALL
SELECT 'bio_evals' AS _set,'current' AS evidence_kind,NULL AS transition_id,e.evaluation_id,e.current_phase_id,e.candidate_phase_id,e.active_visit_id,e.evaluated_at,e.outcome,e.confidence,e.data_quality,e.summary,e.candidate_phase_order,e.candidate_phase_name FROM v_current_biological_candidate_evaluation e JOIN v_active_session a ON a.session_id=e.session_id
ORDER BY candidate_phase_order,evaluated_at;
SELECT 'bio_eval_criteria' AS _set,c.*,IF(c.evaluation_id=current_eval.evaluation_id,c.effective_requirement_display,c.requirement_display) AS required_display,IF(c.evaluation_id=current_eval.evaluation_id AND c.criterion_basis_current=0,'not_evaluated',c.evaluation_status) AS display_evaluation_status,IF(c.evaluation_id=current_eval.evaluation_id AND c.criterion_basis_current=0,'Venter på ny vurdering',c.status_display) AS display_status,IF(c.evaluation_id=current_eval.evaluation_id AND c.criterion_basis_current=0,'Kriteriet er endret. Venter på vurdering med gjeldende krav.',c.explanation) AS display_explanation,IF(c.exception_register_allowed=1,JSON_ARRAY('register_exception'),JSON_ARRAY()) AS allowed_actions FROM v_biological_evaluation_criterion_read_model c LEFT JOIN v_current_biological_candidate_evaluation current_eval ON current_eval.session_id=c.session_id JOIN v_active_session a ON a.session_id=c.session_id WHERE c.evaluation_id IN (SELECT t.evaluation_id FROM v_biological_transition_evidence t WHERE t.session_id=a.session_id UNION SELECT e.evaluation_id FROM v_current_biological_candidate_evaluation e WHERE e.session_id=a.session_id) ORDER BY c.evaluation_id,c.criterion_order;
SELECT 'current_metrics' AS _set,m.* FROM v_current_metric_value m JOIN v_active_session a ON a.session_id=m.session_id WHERE m.metric_id IN ('apparent_attenuation_percent','sg_rate_points_per_day') ORDER BY m.metric_id;
SELECT 'next_process' AS _set,n.process_id,n.process_order,n.name,n.anchor_type,n.anchor_biological_phase_id,n.anchor_offset_hours FROM session_process_steps n JOIN v_active_session_summary s ON s.session_id=n.session_id WHERE n.enabled=1 AND n.process_order>s.current_process_order ORDER BY n.process_order LIMIT 1;
SELECT 'process_steps' AS _set,p.process_id,p.process_order,p.slot_no,p.name,p.description,p.enabled,p.anchor_type,p.anchor_biological_phase_id,p.anchor_offset_hours FROM session_process_steps p JOIN v_active_session a ON a.session_id=p.session_id ORDER BY p.process_order;
SELECT 'process_criteria' AS _set,c.process_id,c.criterion_id,c.criterion_order,c.enabled,c.metric_id,c.model_id,c.role_id,c.label,c.exception_allowed FROM session_process_criteria c JOIN v_active_session a ON a.session_id=c.session_id WHERE c.enabled=1 ORDER BY c.process_id,c.criterion_order;
SELECT 'process_params' AS _set,p.process_id,p.criterion_id,p.model_id,p.parameter_id,p.data_type,p.real_value,p.integer_value,p.boolean_value,p.text_value FROM session_process_criterion_parameter_values p JOIN v_active_session a ON a.session_id=p.session_id ORDER BY p.process_id,p.criterion_id,p.parameter_id;
SELECT 'process_correctable' AS _set,c.process_id,c.criterion_id,c.model_id,c.parameter_id FROM session_process_correctable_parameters c JOIN v_active_session a ON a.session_id=c.session_id ORDER BY c.process_id,c.criterion_id,c.parameter_id;
SELECT 'process_revisions' AS _set,r.owner_id AS process_id,r.criterion_id,r.model_id,r.criterion_revision_id,r.revision_no,r.action,r.note,r.operation_id,r.created_at,r.evaluation_id,r.review_state,r.review_message FROM v_criterion_correction_receipts r JOIN v_active_session a ON a.session_id=r.session_id WHERE r.scope='process' ORDER BY r.owner_id,r.criterion_id;
SELECT 'process_revision_params' AS _set,r.process_id,r.criterion_id,r.criterion_revision_id,p.model_id,p.parameter_id,p.data_type,p.real_value,p.integer_value,p.boolean_value,p.text_value,p.is_unset FROM v_current_process_criterion_revision r JOIN session_process_criterion_revision_parameter_values p ON p.criterion_revision_id=r.criterion_revision_id JOIN v_active_session a ON a.session_id=r.session_id ORDER BY r.process_id,r.criterion_id,p.parameter_id;
SELECT 'process_targets' AS _set,t.process_id,t.target_id,t.target_order,t.metric_id,t.model_id,t.label,t.purpose,e.target_value,r.minimum_value,r.maximum_value FROM session_process_targets t JOIN v_active_session a ON a.session_id=t.session_id LEFT JOIN session_process_target_exact e ON e.session_id=t.session_id AND e.process_id=t.process_id AND e.target_id=t.target_id LEFT JOIN session_process_target_range r ON r.session_id=t.session_id AND r.process_id=t.process_id AND r.target_id=t.target_id ORDER BY t.process_id,t.target_order;
SELECT 'process_actions' AS _set,a.process_id,a.action_id,a.action_order,a.action_type_id,a.label,st.target_id,op.operator_operation_id FROM session_process_actions a JOIN v_active_session v ON v.session_id=a.session_id LEFT JOIN session_process_action_set_target st ON st.session_id=a.session_id AND st.process_id=a.process_id AND st.action_id=a.action_id LEFT JOIN session_process_action_operator op ON op.session_id=a.session_id AND op.process_id=a.process_id AND op.action_id=a.action_id ORDER BY a.process_id,a.action_order;
SELECT 'process_eval' AS _set,e.*,p.name AS current_process_name FROM v_current_process_candidate_evaluation e JOIN v_active_session a ON a.session_id=e.session_id LEFT JOIN session_process_steps p ON p.session_id=e.session_id AND p.process_id=e.current_process_id LIMIT 1;
SELECT 'process_eval_criteria' AS _set,c.*,c.effective_requirement_display AS required_display,IF(c.criterion_basis_current=0,'not_evaluated',c.evaluation_status) AS display_evaluation_status,IF(c.criterion_basis_current=0,'Venter på ny vurdering',c.status_display) AS display_status,IF(c.criterion_basis_current=0,'Kriteriet er endret. Venter på vurdering med gjeldende krav.',c.explanation) AS display_explanation,sc.exception_allowed,IF(c.exception_register_allowed=1,JSON_ARRAY('register_exception'),JSON_ARRAY()) AS allowed_actions FROM v_process_evaluation_criterion_read_model c JOIN v_current_process_candidate_evaluation e ON e.evaluation_id=c.evaluation_id JOIN v_active_session a ON a.session_id=e.session_id LEFT JOIN session_process_criteria sc ON sc.session_id=c.session_id AND sc.process_id=c.candidate_process_id AND sc.criterion_id=c.criterion_id ORDER BY c.criterion_order;
SELECT 'process_exceptions' AS _set,x.* FROM process_criterion_exceptions x JOIN v_current_process_candidate_evaluation e ON e.evaluation_id=x.evaluation_id JOIN v_active_session a ON a.session_id=x.session_id WHERE NOT EXISTS(SELECT 1 FROM process_criterion_exceptions n WHERE n.evaluation_id=x.evaluation_id AND n.criterion_id=x.criterion_id AND n.revision_no>x.revision_no);
SELECT 'process_transition_evals' AS _set,t.* FROM v_process_transition_evidence t JOIN v_active_session a ON a.session_id=t.session_id ORDER BY t.candidate_process_order,t.transitioned_at;
SELECT 'process_transition_eval_criteria' AS _set,c.*,c.requirement_display AS required_display,c.evaluation_status AS display_evaluation_status,c.status_display AS display_status,c.explanation AS display_explanation FROM v_process_evaluation_criterion_read_model c JOIN v_process_transition_evidence t ON t.evaluation_id=c.evaluation_id JOIN v_active_session a ON a.session_id=t.session_id ORDER BY t.candidate_process_order,c.criterion_order;
SELECT 'recommendation' AS _set,r.* FROM v_recommendations_effective r JOIN v_active_session a ON a.session_id=r.session_id WHERE r.effective_status='pending' ORDER BY r.created_at DESC LIMIT 1;
SELECT 'report_summary' AS _set,r.* FROM v_active_session_report_summary r LIMIT 1;

SELECT 'measurement_gaps' AS _set,g.gap_started_at,g.gap_ended_at,g.duration_seconds,g.source FROM v_measurement_data_gaps g JOIN v_active_session a ON a.session_id=g.session_id ORDER BY g.gap_started_at;
SELECT 'analysis_graphs' AS _set,g.* FROM v_graph_definitions g JOIN v_active_session a ON a.session_id=g.session_id WHERE g.render_scope='dashboard' ORDER BY g.sort_order;
SELECT 'analysis_series' AS _set,s.* FROM v_graph_series s JOIN v_active_session live ON live.session_id=s.session_id ORDER BY s.graph_id,s.series_id,s.sample_at;
SELECT 'analysis_latest' AS _set,s.* FROM v_graph_latest s JOIN v_active_session a ON a.session_id=s.session_id ORDER BY s.graph_id,s.series_id,s.sort_order;
SELECT 'analysis_time_markers' AS _set,m.* FROM v_graph_time_markers m JOIN v_active_session a ON a.session_id=m.session_id WHERE m.render_scope='dashboard' ORDER BY m.graph_id,m.marker_at;
SELECT 'analysis_requirements' AS _set,r.* FROM v_active_analysis_requirements r ORDER BY r.graph_id,r.owner_type,r.owner_id,r.criterion_id;
SELECT 'analysis_bio_markers' AS _set,m.* FROM v_active_analysis_biological_markers m JOIN v_active_session a ON a.session_id=m.session_id ORDER BY m.graph_id,m.started_at;
SELECT 'analysis_process_markers' AS _set,m.* FROM v_active_analysis_process_markers m JOIN v_active_session a ON a.session_id=m.session_id ORDER BY m.graph_id,m.started_at;
SELECT 'bio_exceptions' AS _set,x.* FROM biological_criterion_exceptions x JOIN v_current_biological_candidate_evaluation e ON e.evaluation_id=x.evaluation_id WHERE NOT EXISTS(SELECT 1 FROM biological_criterion_exceptions n WHERE n.evaluation_id=x.evaluation_id AND n.criterion_id=x.criterion_id AND n.revision_no>x.revision_no);
SELECT 'analysis_reference_bands' AS _set,r.* FROM v_graph_reference_bands r JOIN v_active_session a ON a.session_id=r.session_id;
SELECT 'analysis_axis_ticks' AS _set,t.* FROM v_graph_axis_ticks t WHERE t.session_id=(SELECT session_id FROM v_active_session LIMIT 1);
SELECT 'overview_ticks' AS _set,t.* FROM v_graph_axis_ticks t WHERE t.session_id=(SELECT session_id FROM v_active_session LIMIT 1);

SELECT 'demo_options' AS _set,d.* FROM v_dashboard_demo_options d ORDER BY d.name;SELECT 'demo_selection' AS _set,d.* FROM v_demo_profile_selection d;SELECT 'comparison_options' AS _set,d.* FROM v_dashboard_reference_options d;SELECT 'graph_selection' AS _set,d.* FROM v_graph_display_selection d;SELECT 'graph_view_options' AS _set,d.* FROM v_dashboard_graph_view_options d;SELECT 'comparison_series' AS _set,m.*,m.bucket_at AS at,m.sg_value AS sg,m.temperature_mean_c AS temperature_c,m.pressure_mean_bar AS pressure_bar,'#ef6c00' AS line_color FROM v_graph_reference_measurement_series m JOIN v_session_graph_time_axis axis ON axis.session_id=m.session_id WHERE m.bucket_at BETWEEN axis.x_axis_started_at AND axis.x_axis_ended_at ORDER BY m.bucket_at;
SELECT 'graph_labels' AS _set,l.* FROM v_dashboard_graph_labels l;
SELECT 'process_guidance' AS _set,v.* FROM v_current_process_guidance v JOIN v_active_session a ON a.session_id=v.session_id; SELECT 'runtime_presentation' AS _set,v.* FROM v_session_runtime_presentation v JOIN v_active_session a ON a.session_id=v.session_id;SELECT 'bio_pending' AS _set,p.phase_id,p.phase_order,p.name AS phase_name,'not_evaluated' AS outcome,'not_yet' AS availability FROM session_biological_phases p JOIN v_active_session_summary s ON s.session_id=p.session_id WHERE p.phase_order=(SELECT MIN(n.phase_order) FROM session_biological_phases n WHERE n.session_id=p.session_id AND n.phase_order>s.current_biological_phase_order) AND NOT EXISTS(SELECT 1 FROM v_current_biological_candidate_evaluation e WHERE e.session_id=p.session_id);

SELECT 'bio_effective_params' AS _set,p.* FROM v_effective_biological_criterion_parameters p JOIN v_active_session a ON a.session_id=p.session_id;

SELECT 'process_effective_params' AS _set,p.* FROM v_effective_process_criterion_parameters p JOIN v_active_session a ON a.session_id=p.session_id;

SELECT 'historical_phase_options' AS _set,o.* FROM v_historical_phase_options o ORDER BY o.kind,o.sort_order;

SELECT 'phase_durations' AS _set,d.* FROM v_phase_duration_presentation d JOIN v_active_session a ON a.session_id=d.session_id;

SELECT 'import_coverage' AS _set,c.* FROM v_session_import_coverage c WHERE EXISTS(SELECT 1 FROM v_active_session a WHERE a.session_id=c.session_id);
